using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
[InitializeOnLoad]static class HumanTrimSixSecondsOnce{static HumanTrimSixSecondsOnce(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||File.Exists("D:/-11-scene3-audit/human-six-second-trim.txt"))return;var path="Assets/Scene3Human/HumanPerformance.anim";var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(!clip)return;EditorApplication.update-=Run;try{if(clip.length<6f)throw new Exception("Clip shorter than six seconds");File.Copy(Path.GetFullPath(path),"D:/-11-scene3-audit/HumanPerformance-before-six-seconds.anim",true);Undo.RecordObject(clip,"Trim human animation to first 6 seconds");foreach(var binding in AnimationUtility.GetCurveBindings(clip)){var curve=AnimationUtility.GetEditorCurve(clip,binding);if(curve==null||curve.length==0)continue;float value=curve.Evaluate(6f);var keys=curve.keys.Where(k=>k.time<6f).ToList();var matching=curve.keys.Where(k=>Mathf.Abs(k.time-6f)<.00001f).ToArray();keys.Add(matching.Length>0?matching[0]:new Keyframe(6f,value));curve.keys=keys.ToArray();AnimationUtility.SetEditorCurve(clip,binding,curve);}foreach(var binding in AnimationUtility.GetObjectReferenceCurveBindings(clip))AnimationUtility.SetObjectReferenceCurve(clip,binding,AnimationUtility.GetObjectReferenceCurve(clip,binding).Where(k=>k.time<=6f).ToArray());AnimationUtility.SetAnimationEvents(clip,AnimationUtility.GetAnimationEvents(clip).Where(e=>e.time<=6f).ToArray());var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.startTime=0;settings.stopTime=6;settings.loopTime=true;AnimationUtility.SetAnimationClipSettings(clip,settings);EditorUtility.SetDirty(clip);AssetDatabase.SaveAssets();AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);var updated=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(Mathf.Abs(updated.length-6f)>.02f)throw new Exception("Unexpected length "+updated.length);File.WriteAllText("D:/-11-scene3-audit/human-six-second-trim.txt","length="+updated.length+" loop="+AnimationUtility.GetAnimationClipSettings(updated).loopTime);}catch(Exception e){File.WriteAllText("D:/-11-scene3-audit/human-six-second-error.txt",e.ToString());}}}

#endif
